/**
 * yield-bar.tsx
 * Solid.js yield bar
 */
import { For, Match, Show, splitProps, Switch, type Component, type JSX } from "solid-js";

import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

import { Pill } from "./pills.jsx";

/** Visual style for a yield bar entry. */
export enum YieldBarEntryStyle {
	NONE,
	GAIN,
	LOSS,
}

/** Data for a single yield bar entry. */
export interface YieldBarEntry {
	/** Icon identifier for the entry. */
	type: string;
	/** Numeric value shown for the entry. */
	value: number;
	/** Visual container style for the entry. */
	style: YieldBarEntryStyle;
	/** Optional icon context passed to Icon. */
	iconContext?: string;
}

/** Display variant for the yield bar. */
export type YieldBarVariant = "default" | "compact";

/** Props for the YieldBar component. */
export interface YieldBarProps extends JSX.HTMLAttributes<HTMLDivElement> {
	/** Ordered entries rendered in the yield bar. */
	yieldBarData: YieldBarEntry[];
	/** Optional per-entry delta values rendered above entries by index. */
	yieldBarDeltas?: YieldBarEntry[];
	/** Display variant. "compact" uses pill-shaped containers. @default "default" */
	variant?: YieldBarVariant;
}

const getEntryContainerClass = (style: YieldBarEntryStyle): string => {
	switch (style) {
		case YieldBarEntryStyle.GAIN:
			return "img-yield-container-positive";
		case YieldBarEntryStyle.LOSS:
			return "img-yield-container-negative";
		case YieldBarEntryStyle.NONE:
			return "img-yield-container-neutral";
		default:
			style satisfies never;
			return "img-yield-container-neutral";
	}
};

const formatYieldValue = (value: number): number => (value > 100 ? Math.trunc(value) : Math.trunc(value * 10) / 10);

const hasDeltaValue = (delta: YieldBarEntry | undefined): delta is YieldBarEntry => {
	return delta !== undefined && delta.value !== 0;
};

const getDeltaTextClass = (style: YieldBarEntryStyle): string => {
	switch (style) {
		case YieldBarEntryStyle.GAIN:
			return "text-positive-light";
		case YieldBarEntryStyle.LOSS:
			return "text-negative-light";
		case YieldBarEntryStyle.NONE:
		default:
			return "";
	}
};

interface YieldEntryProps {
	entry: YieldBarEntry;
	delta?: YieldBarEntry;
}

/** Default yield entry with background image container. */
const DefaultYieldEntry: Component<YieldEntryProps> = (props) => (
	<>
		<Show when={hasDeltaValue(props.delta)}>
			<div
				class="flex items-center justify-center w-11 h-6 mb-2 text-sm"
				style={{
					"background-color": "rgba(0,0,0,0.51)",
					"border-radius": "5px",
				}}
			>
				<div
					class={getDeltaTextClass(props.delta!.style)}
					style={{ "letter-spacing": "-0.5px" }}
				>
					<L10n.Compose
						text="LOC_UI_CITY_DETAILS_YIELD_ONE_DECIMAL"
						args={[props.delta!.value]}
					/>
				</div>
			</div>
		</Show>
		<div
			class={`w-11 h-20 flex flex-col items-center justify-center self-end ${getEntryContainerClass(props.entry.style)}`}
		>
			<Icon
				class="mt-2 size-8 self-center"
				name={props.entry.type}
				context={props.entry.iconContext}
			/>
			<L10n.Stylize
				class="mb-2 text-sm text-center font-fit-shrink"
				style={{ "letter-spacing": "-0.5px" }}
				text="LOC_UI_YIELD_ONE_DECIMAL_NO_PLUS"
				args={[formatYieldValue(props.entry.value)]}
			/>
		</div>
	</>
);

/** Compact pill-shaped yield entry. */
const CompactYieldEntry: Component<YieldEntryProps> = (props) => (
	<>
		<Show when={hasDeltaValue(props.delta)}>
			<div
				class={`flex items-center justify-center text-xs ${getDeltaTextClass(props.delta!.style)}`}
				style={{ "letter-spacing": "-0.5px" }}
			>
				<L10n.Compose
					text="LOC_UI_CITY_DETAILS_YIELD_ONE_DECIMAL"
					args={[props.delta!.value]}
				/>
			</div>
		</Show>
		<Pill
			class="text-sm"
			small
		>
			<div class="flex items-center">
				<Icon
					class="size-6 -ml-0\.5"
					name={props.entry.type}
					context={props.entry.iconContext}
				/>
				<L10n.Stylize
					class="text-sm font-fit-shrink"
					style={{ "letter-spacing": "-0.5px" }}
					text="LOC_UI_YIELD_ONE_DECIMAL_NO_PLUS"
					args={[formatYieldValue(props.entry.value)]}
				/>
			</div>
		</Pill>
	</>
);

const YieldBarComponent: Component<YieldBarProps> = (props) => {
	const [local, other] = splitProps(props, ["yieldBarData", "yieldBarDeltas", "variant", "class"]);
	const variant = () => local.variant ?? "default";

	return (
		<div
			class={`flex justify-between items-center gap-2 ${local.class ?? ""}`}
			{...other}
		>
			<For each={local.yieldBarData}>
				{(entry, index) => {
					const delta = () => local.yieldBarDeltas?.[index()];
					return (
						<Switch>
							<Match when={variant() === "compact"}>
								<CompactYieldEntry
									entry={entry}
									delta={delta()}
								/>
							</Match>
							<Match when={variant() === "default"}>
								<DefaultYieldEntry
									entry={entry}
									delta={delta()}
								/>
							</Match>
						</Switch>
					);
				}}
			</For>
		</div>
	);
};

export const YieldBar = ComponentRegistry.register("YieldBar", YieldBarComponent);
